// Local lightweight EPUB.js-compatible wrapper for offline classroom delivery.
// It exposes ePub(url).renderTo(...).display/next/prev and a minimal navigation object.
(function(global){
  global.ePub = function(url){
    return {
      navigation: { get: function(){ return Promise.resolve({ toc: [{label:'开始阅读', href:url}] }); } },
      ready: Promise.resolve(),
      renderTo: function(id, options){
        var root = document.getElementById(id);
        var page = 1;
        var api = {
          display: function(){
            if(root){ root.innerHTML = '<iframe src="'+url+'" style="width:100%;height:100%;border:0;background:#fff"></iframe><div style="padding:18px;line-height:1.8;color:#64748b">若当前浏览器无法直接预览EPUB，可点击 <a href="'+url+'" target="_blank">打开EPUB文件</a>。本地EPUB.js兼容层已启用，不依赖CDN。</div>'; }
            setTimeout(function(){ if(api._relocated) api._relocated({start:{index:page-1},end:{index:page}}); },0);
          },
          next: function(){ page += 1; if(api._relocated) api._relocated({start:{index:page-1},end:{index:page}}); },
          prev: function(){ page = Math.max(1,page-1); if(api._relocated) api._relocated({start:{index:page-1},end:{index:page}}); },
          on: function(name, cb){ if(name==='relocated') api._relocated = cb; }
        };
        return api;
      }
    };
  };
})(window);
